                    TextureAtlasSprite sprite = this.armorTrimAtlas.getSprite(armorTrim.outerTexture(armorItem.getMaterial()));
                    renderer.getModel().rightLegPartArmors().forEach(part -> {
                        matrixStackIn.pushPose();
